1	// The assistant helper: the agent loop, run by the Anthropic SDK's Tool
2	// Runner, in a separate process the app launches from Contents/Helpers. It
3	// speaks JSON lines over stdio (protocol.ts) and owns no tools itself: every
4	// tool call goes back to the app, which runs it through the same dispatcher
5	// its MCP server uses. Two apps carry agent/src/ byte for byte, Rasterize
6	// and Frame Job: a change is one diff applied to both, and whatever differs
7	// between them arrives in `configure`.
8	
9	import Anthropic from "@anthropic-ai/sdk";
10	import type {
11	  BetaMessage,
12	  BetaTool,
13	  BetaMessageParam,
14	  BetaToolResultContentBlockParam,
15	} from "@anthropic-ai/sdk/resources/beta/messages";
16	import type { BetaRunnableTool } from "@anthropic-ai/sdk/lib/tools/BetaRunnableTool";
17	import { ToolError } from "@anthropic-ai/sdk/lib/tools/ToolError";
18	import { createInterface } from "node:readline";
19	import { price } from "./pricing";
20	import { initialPrices, refreshPrices } from "./priceTable";
21	import type { LoadedPrices, PriceOptions } from "./priceTable";
22	import type {
23	  CallToolResult,
24	  CatalogTool,
25	  ChatSettings,
26	  Configure,
27	  HostMessage,
28	  HelperEvent,
29	} from "./protocol";
30	
31	/** Hard ceiling on API rounds within one turn. */
32	const MAX_ITERATIONS = 30;
33	/** Thinking counts toward this as well as the reply. */
34	const MAX_TOKENS = 32000;
35	
36	const TOOL_SEARCH = {
37	  type: "tool_search_tool_bm25_20251119",
38	  name: "tool_search_tool_bm25",
39	} as const;
40	
41	/**
42	 * Old tool results are cleared, when the user turns it on, only past this
43	 * many tokens in context and in chunks of at least CLEAR_AT_LEAST, so the
44	 * prompt cache breaks rarely. The API applies it per request, so it can
45	 * fire mid-turn; it never touches tool search results (server-side).
46	 */
47	const CLEAR_TRIGGER_TOKENS = 150_000;
48	const CLEAR_AT_LEAST_TOKENS = 50_000;
49	const CLEAR_KEEP_TOOL_USES = 5;
50	
51	/** Betas every request carries: progress notes, refusal fallback, and compaction blocks. */
52	const BASE_BETAS = [
53	  "thinking-display-updates-2026-08-18",
54	  "server-side-fallback-2026-07-01",
55	  "compact-2026-09-04",
56	];
57	
58	let client: Anthropic | undefined;
59	let config: Configure | undefined;
60	/** Chat Settings; configure sets them and a settings message replaces them between turns. */
61	let settings: ChatSettings = { auto_compact_tokens: 300_000, clear_tool_results: false };
62	let tools: BetaRunnableTool[] = [];
63	let history: BetaMessageParam[] = [];
64	let turn: AbortController | undefined;
65	let nextCallID = 0;
66	/** Tokens in the conversation as of the last response, and the model's window. */
67	let contextUsed = 0;
68	let contextLimit: number | null = null;
69	const pendingCalls = new Map<string, (result: CallToolResult | null) => void>();
70	/** The price table in force; a turn takes it once, at its start (spec §11 P-5). */
71	let prices: LoadedPrices | undefined;
72	
73	function emit(event: HelperEvent) {
74	  process.stdout.write(JSON.stringify(event) + "\n");
75	}
76	
77	function configure(message: Configure) {
78	  config = message;
79	  client = new Anthropic({
80	    apiKey: message.api_key,
81	    baseURL: message.api_base ?? "https://api.anthropic.com",
82	    maxRetries: 3,
83	  });
84	  const core = new Set(message.core_tools);
85	  tools = message.tools.map((entry) => runnableTool(entry, core));
86	  settings = message.settings;
87	  void lookUpContextLimit(message.model);
88	  setUpPrices({ cache: message.price_cache, feed: message.price_feed });
89	}
90	
91	/** The prices at `configure`: reported now when no refresh is due, else once
92	 *  the refresh settles, in the same continuation that puts it in force. */
93	function setUpPrices(options: PriceOptions) {
94	  const initial = initialPrices(options);
95	  prices = initial.prices;
96	  if (!initial.refreshDue) {
97	    emit({ type: "prices", source: initial.prices.source });
98	    return;
99	  }
100	  void refreshPrices(initial.prices, options).then((loaded) => {
101	    prices = loaded;
102	    emit({ type: "prices", source: loaded.source });
103	  });
104	}
105	
106	/** What one response cost, at the prices its turn started with; `partial` for one cut short. */
107	function emitCost(message: BetaMessage, turnPrices: LoadedPrices, partial?: true) {
108	  emit({
109	    type: "cost",
110	    model: message.model,
111	    usage: message.usage,
112	    cost: price(message.usage, message.model, turnPrices.table),
113	    prices: turnPrices.source,
114	    ...(partial ? { partial } : {}),
115	  });
116	}
117	
118	/** The model's context window, from the Models API, for the panel's meter. */
119	async function lookUpContextLimit(model: string) {
120	  try {
121	    const info = await client!.models.retrieve(model);
122	    contextLimit = info.max_input_tokens ?? null;
123	  } catch {
124	    contextLimit = null; // the meter shows usage without a limit
125	  }
126	  emitContextUsage();
127	}
128	
129	function emitContextUsage() {
130	  emit({ type: "context_usage", used: contextUsed, limit: contextLimit });
131	}
132	
133	/** Wraps one catalog entry: running it asks the app and waits for the answer. */
134	function runnableTool(entry: CatalogTool, core: ReadonlySet<string>): BetaRunnableTool {
135	  return {
136	    name: entry.name,
137	    description: entry.description,
138	    input_schema: entry.inputSchema as BetaTool["input_schema"],
139	    defer_loading: core.has(entry.name) ? undefined : true,
140	    parse: (input: unknown) => input,
141	    run: async (input: unknown) => {
142	      emit({ type: "tool_call", name: entry.name, arguments: input });
143	      const callID = String(++nextCallID);
144	      const result = await new Promise<CallToolResult | null>((resolve) => {
145	        pendingCalls.set(callID, resolve);
146	        emit({ type: "tool_request", call_id: callID, name: entry.name, arguments_json: JSON.stringify(input) });
147	      });
148	      const { blocks, isError, summary } = convertToolResult(result);
149	      emit({ type: "tool_result", name: entry.name, is_error: isError, summary });
150	      if (isError) throw new ToolError(blocks);
151	      return blocks;
152	    },
153	  };
154	}
155	
156	/** MCP CallToolResult -> Messages API tool_result content, plus a one-line summary for the panel. */
157	function convertToolResult(result: CallToolResult | null): {
158	  blocks: BetaToolResultContentBlockParam[];
159	  isError: boolean;
160	  summary: string;
161	} {
162	  const failure = (message: string) => ({
163	    blocks: [{ type: "text" as const, text: message }],
164	    isError: true,
165	    summary: message,
166	  });
167	  if (!result) return failure("The tool failed to execute.");
168	  const blocks: BetaToolResultContentBlockParam[] = [];
169	  let summary = "";
170	  for (const item of result.content ?? []) {
171	    if (item.type === "text") {
172	      const text = item.text ?? "";
173	      if (!summary) summary = text.slice(0, 200);
174	      blocks.push({ type: "text", text });
175	    } else if (item.type === "image") {
176	      if (!summary) summary = "(image)";
177	      blocks.push({
178	        type: "image",
179	        source: {
180	          type: "base64",
181	          media_type: (item.mimeType ?? "image/png") as "image/png",
182	          data: item.data ?? "",
183	        },
184	      });
185	    }
186	  }
187	  if (blocks.length === 0) return failure("The tool returned no content.");
188	  return { blocks, isError: result.isError === true, summary };
189	}
190	
191	/** Appends user text, merging into a trailing user message (e.g. cancelled tool results). */
192	function pushUserText(text: string) {
193	  const last = history.at(-1);
194	  if (last?.role === "user") {
195	    const content = typeof last.content === "string" ? [{ type: "text" as const, text: last.content }] : last.content;
196	    last.content = [...content, { type: "text", text }];
197	  } else {
198	    history.push({ role: "user", content: [{ type: "text", text }] });
199	  }
200	}
201	
202	// History is append-only: nothing already sent is ever rewritten. Opus 5.5
203	// replays its earlier thinking blocks only while everything before them is
204	// byte-identical (and rejects the request outright on newer accounts), and
205	// an unchanged prefix is also what keeps the prompt cache warm. Old canvas
206	// renders therefore stay in history. The one sanctioned rewrite is the
207	// API's own on-demand compaction, which swaps the history for its signed
208	// summary block at the end of a turn (compactIfDue).
209	
210	/** Whether the conversation has outgrown the auto-compact limit. */
211	function compactionDue(): boolean {
212	  const limit = settings.auto_compact_tokens;
213	  return limit !== null && contextUsed >= limit;
214	}
215	
216	/** Tool result clearing, when on; see CLEAR_TRIGGER_TOKENS. */
217	function contextManagement() {
218	  if (!settings.clear_tool_results) return undefined;
219	  return {
220	    edits: [
221	      {
222	        type: "clear_tool_uses_20250919" as const,
223	        trigger: { type: "input_tokens" as const, value: CLEAR_TRIGGER_TOKENS },
224	        keep: { type: "tool_uses" as const, value: CLEAR_KEEP_TOOL_USES },
225	        clear_at_least: { type: "input_tokens" as const, value: CLEAR_AT_LEAST_TOKENS },
226	      },
227	    ],
228	  };
229	}
230	
231	async function runTurn(text: string) {
232	  if (!client || !config || !prices) {
233	    emit({ type: "error", message: "The assistant helper was not configured." });
234	    return;
235	  }
236	  if (turn) {
237	    emit({ type: "error", message: "The assistant is busy." });
238	    return;
239	  }
240	  const controller = new AbortController();
241	  turn = controller;
242	  const turnPrices = prices;
243	  emit({ type: "turn_started" });
244	  pushUserText(text);
245	
246	  const runner = client.beta.messages.toolRunner(
247	    {
248	      model: config.model,
249	      max_tokens: MAX_TOKENS,
250	      max_iterations: MAX_ITERATIONS,
251	      system: `${config.system}\n\n${config.search_guide}`,
252	      tools: [TOOL_SEARCH, ...tools],
253	      messages: history,
254	      // Automatic caching: the breakpoint moves to the newest block each
255	      // round, so the tool catalog, system prompt and history are reused.
256	      cache_control: { type: "ephemeral" },
257	      // Thinking is always on for Opus 5.5; effort is the dial (its API
258	      // default is also medium, set here so it doesn't drift).
259	      output_config: { effort: "medium" },
260	      // The model's notes between tool calls arrive as thinking blocks;
261	      // "updates" returns them as short readable summaries.
262	      thinking: { type: "adaptive", display: "updates" },
263	      // A classifier refusal is retried on the model Anthropic picks for it.
264	      fallbacks: "default",
265	      context_management: contextManagement(),
266	      betas: settings.clear_tool_results
267	        ? [...BASE_BETAS, "context-management-2025-06-27"]
268	        : BASE_BETAS,
269	      stream: true,
270	    },
271	    { signal: controller.signal },
272	  );
273	
274	  let last: BetaMessage | undefined;
275	  let compacting = false;
276	  // The response in flight, as its stream has reported it so far: priced as
277	  // partial if the turn throws before `finalMessage` resolves (an object, so
278	  // tsc does not narrow the property to `never` in the catch).
279	  const inFlight: { message?: BetaMessage } = {};
280	  try {
281	    for await (const stream of runner) {
282	      stream.on("streamEvent", (_event, snapshot) => {
283	        inFlight.message = snapshot;
284	      });
285	      stream.on("text", (delta) => emit({ type: "text_delta", text: delta }));
286	      stream.on("thinking", (delta) => emit({ type: "progress_delta", text: delta }));
287	      const message = await stream.finalMessage();
288	      inFlight.message = undefined;
289	
290	      if (compacting) {
291	        // The summary request the runner sent after the final reply.
292	        compacting = false;
293	        emitCost(message, turnPrices);
294	        reportCompaction(message);
295	        continue;
296	      }
297	
298	      last = message;
299	      emit({ type: "message_done", stop_reason: message.stop_reason, usage: message.usage });
300	      emitCost(message, turnPrices);
301	      // Everything this request sent (cached or not) plus the reply, which
302	      // becomes part of the next request.
303	      const usage = message.usage;
304	      contextUsed =
305	        usage.input_tokens +
306	        (usage.cache_read_input_tokens ?? 0) +
307	        (usage.cache_creation_input_tokens ?? 0) +
308	        usage.output_tokens;
309	      emitContextUsage();
310	      reportClearedToolResults(message);
311	
312	      // Compaction only ever runs when a turn ends: after the final reply,
313	      // never between tool calls. The runner sends the summary request next
314	      // and swaps its history for the returned block.
315	      const final = message.stop_reason !== "tool_use" && message.stop_reason !== "pause_turn";
316	      if (final && compactionDue() && !controller.signal.aborted) {
317	        compacting = true;
318	        emit({ type: "compaction_started", used: contextUsed });
319	        runner.compactBeforeNextTurn({ type: "summarize", instructions: config.compaction_instructions });
320	      }
321	    }
322	    if (compacting) {
323	      // The runner ended without handing back a summary.
324	      emit({ type: "compaction_failed", reason: "no summary came back" });
325	    }
326	    if (last?.stop_reason === "max_tokens") {
327	      emit({ type: "error", message: "The reply was cut off at the output limit." });
328	    } else if (last?.stop_reason === "refusal") {
329	      emit({ type: "error", message: "The model declined this request." });
330	    }
331	  } catch (error) {
332	    if (inFlight.message) {
333	      emitCost(inFlight.message, turnPrices, true);
334	      inFlight.message = undefined;
335	    }
336	    if (!controller.signal.aborted) {
337	      emit({ type: "error", message: errorMessage(error) });
338	    }
339	  } finally {
340	    // The runner keeps its own copy of the conversation, including
341	    // tool results that landed before a cancel or an error.
342	    history = [...runner.params.messages];
343	    turn = undefined;
344	    emit({ type: "turn_finished" });
345	  }
346	}
347	
348	/** A compaction response: the summary block replaced the history, or nothing did. */
349	function reportCompaction(message: BetaMessage) {
350	  if (message.stop_reason !== "compaction") {
351	    // The history is unchanged; the next turn end tries again.
352	    emit({ type: "compaction_failed", reason: `the summary stopped with ${message.stop_reason}` });
353	    return;
354	  }
355	  const before = contextUsed;
356	  const summary = message.usage.iterations?.find((entry) => entry.type === "compaction");
357	  // The summary is what remains of the conversation; the next response's
358	  // usage replaces this estimate with the real figure.
359	  contextUsed = summary?.output_tokens ?? 0;
360	  emit({ type: "compacted", before, after: contextUsed });
361	  emitContextUsage();
362	}
363	
364	/** Tells the panel when the API cleared old tool results from this request. */
365	function reportClearedToolResults(message: BetaMessage) {
366	  for (const edit of message.context_management?.applied_edits ?? []) {
367	    if (edit.type === "clear_tool_uses_20250919") {
368	      emit({
369	        type: "tool_results_cleared",
370	        tool_uses: edit.cleared_tool_uses,
371	        tokens: edit.cleared_input_tokens,
372	      });
373	    }
374	  }
375	}
376	
377	function errorMessage(error: unknown): string {
378	  if (error instanceof Anthropic.APIError) {
379	    const detail = (error.error as { error?: { message?: string } } | undefined)?.error?.message;
380	    return `API error ${error.status ?? ""}: ${detail ?? error.message}`.trim();
381	  }
382	  return error instanceof Error ? error.message : String(error);
383	}
384	
385	function handle(message: HostMessage) {
386	  switch (message.type) {
387	    case "configure":
388	      configure(message);
389	      emit({ type: "ready" });
390	      break;
391	    case "send":
392	      void runTurn(message.text);
393	      break;
394	    case "cancel":
395	      turn?.abort();
396	      break;
397	    case "tool_result": {
398	      const resolve = pendingCalls.get(message.call_id);
399	      pendingCalls.delete(message.call_id);
400	      resolve?.(message.result);
401	      break;
402	    }
403	    case "settings":
404	      // Applies from the next turn; a running turn keeps what it started with.
405	      settings = message.settings;
406	      break;
407	    case "reset":
408	      turn?.abort();
409	      history = [];
410	      contextUsed = 0;
411	      emitContextUsage();
412	      break;
413	  }
414	}
415	
416	const input = createInterface({ input: process.stdin });
417	input.on("line", (line) => {
418	  if (!line.trim()) return;
419	  try {
420	    handle(JSON.parse(line) as HostMessage);
421	  } catch (error) {
422	    emit({ type: "error", message: `Bad message from the app: ${errorMessage(error)}` });
423	  }
424	});
425	// The app closing our stdin means it is gone or closed the session.
426	input.on("close", () => process.exit(0));
427

